Can you refactor this utility module for our "ParkRanger" campground reservation app? Right now `utils/dateHelpers.js` mixes CommonJS `require` calls with ES module `import` statements, uses `var` everywhere, and has no type safety. I'd like you to convert it to a proper `.ts` file with ES module syntax throughout, add TypeScript interfaces for the `ReservationSlot` and `AvailabilityWindow` objects that get passed around, replace `var` with `const`/`let` as appropriate, and swap out the manual `for` loops with `map`/`filter`/`reduce` where it makes sense. Also, the `calculateNightlyRate` function currently returns `undefined` when the date range is invalid instead of throwing — can you add proper return type annotations and handle that edge case? Here's the current file:
```js
var moment = require('moment');
import { addDays } from 'date-fns';
var _ = require('lodash');

var SEASON_MULTIPLIERS = {
  peak: 1.5,
  shoulder: 1.2,
  off: 1.0
};

var BASE_RATE = 35;

function getSeasonForDate(date) {
  var month = date.getMonth();
  if (month >= 5 && month <= 8) return 'peak';
  if (month >= 3 && month <= 4 || month >= 9 && month <= 10) return 'shoulder';
  return 'off';
}

function calculateNightlyRate(checkIn, checkOut) {
  var start = new Date(checkIn);
  var end = new Date(checkOut);
  if (end <= start) return undefined;

  var totalRate = 0;
  for (var d = new Date(start); d < end; d.setDate(d.getDate() + 1)) {
    var season = getSeasonForDate(d);
    totalRate += BASE_RATE * SEASON_MULTIPLIERS[season];
  }
  return totalRate;
}

